/** 
 * Get a vital sign value.
 */
public Double getVitalSign(VitalSign vitalSign,long time){
  ValueGenerator valueGenerator=vitalSigns.get(vitalSign);
  if (valueGenerator == null) {
    throw new NullPointerException("Vital sign '" + vitalSign + "' not set. Valid vital signs: "+ vitalSigns.keySet());
  }
  double value=valueGenerator.getValue(time);
  int decimalPlaces;
switch (vitalSign) {
case DIASTOLIC_BLOOD_PRESSURE:case SYSTOLIC_BLOOD_PRESSURE:case HEART_RATE:case RESPIRATION_RATE:    decimalPlaces=0;
  break;
case HEIGHT:case WEIGHT:decimalPlaces=1;
break;
default:decimalPlaces=2;
}
Double retVal=value;
try {
retVal=BigDecimal.valueOf(value).setScale(decimalPlaces,RoundingMode.HALF_UP).doubleValue();
}
 catch (NumberFormatException e) {
}
return retVal;
}
